"use server";

/**
 * Return to Work: drafting one with AI, and recording it as Evidence.
 *
 * The draft is a convenience, never a substitute for the conversation. It fills the
 * "Prepared for you" section from the absence record and the manager edits everything
 * before completing. Nothing is stored until they complete the form, so a draft they
 * dislike costs one AI credit and leaves no trace on the employee's file.
 *
 * THE QUESTIONS ARE DRAFTED, NOT FIXED (v3, migration 0147). Phil: "I wanted those
 * question fields generated by the ai when they press 'draft it for me' as not every
 * absence will be the same." So the model returns a small set of questions as STRICT
 * JSON, the dialog renders each as a real labelled control, and the answers are written
 * back into the single tailored_questions long_text as readable text. The questions
 * cannot be schema fields: Evidence pins a form_version id and the server validates
 * every answer against that stored schema, so a key invented this morning would be
 * dropped, and a version per absence would wreck the audit trail.
 *
 * ALL OF THEM, NOT JUST THE HEALTH ONES (v4, migration 0148). Phil: "'The conversation'
 * tile ... needs to also be ai and relevent to the absence." The fixed core v3 left
 * behind (fit to return, ongoing symptoms, work related, adjustments, support agreed) is
 * gone from the form, so the prompt below now REQUIRES the drafted set to cover that
 * ground. Referral and follow up date stay as real fields: they record what the manager
 * did, not what they asked.
 */

import { revalidatePath } from "next/cache";
import { requireCompany } from "@/lib/auth/guards";
import { createClient } from "@/lib/supabase/server";
import { createServiceClient } from "@/lib/supabase/admin";
import { writeAudit } from "@/lib/audit";
import { runAi } from "@/lib/ai/anthropic";
import { submitEvidence, type EvidenceFileInput } from "@/lib/evidence/submit";
import { getCompanyFormByKey } from "@/lib/people/data";
import { getRtwContext } from "./rtw";
import type { Answers } from "@/lib/form-schema";
import { AI_QUESTION_LIMIT, stripJsonFence, toAiQuestions, type ActionState, type AiQuestion } from "@/lib/forms";
import { getRtwQuestionnaire } from "@/lib/absence/rtw-questions-data";
import { redactName } from "@/lib/absence/meeting-questions";
import {
  RTW_SYSTEM,
  checkRtwDraft,
  checkRtwSummary,
  rtwDraftPrompt,
  type RtwAbsence,
} from "@/lib/absence/rtw-draft-rules";
import { changedAnswerNumbers, rtwProvenanceNote } from "@/lib/absence/rtw-questions";
import { RTW_ROLE_REFUSAL, canRecordReturnToWork } from "./rtw-roles";

// v5 (Phil, 2026-10-13): the instructions, the input and the check after the reply live in
// lib/absence/rtw-draft-rules.ts. A Return to Work is about THIS absence only; the fit note follows
// GOV.UK's 7 calendar days; work as a cause only when the reason points to work. The v1 guardrails
// stand: never diagnose, never speculate about a medical cause, never suggest an outcome.

/**
 * Read the model's reply as { summary, questions }. Defensive on purpose: strip any
 * fence, parse in a try/catch, accept either the object we asked for or a bare array,
 * and drop any question whose shape is wrong (see toAiQuestions). questions is [] when
 * nothing survives, which tells the caller to fall back to prose. This NEVER throws.
 */
function readDraft(raw: string): { summary: string; questions: AiQuestion[] } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(stripJsonFence(raw));
  } catch {
    return { summary: "", questions: [] };
  }
  if (Array.isArray(parsed)) return { summary: "", questions: toAiQuestions(parsed) };
  if (parsed && typeof parsed === "object") {
    const obj = parsed as Record<string, unknown>;
    const summary = typeof obj.summary === "string" ? obj.summary.trim() : "";
    return { summary, questions: toAiQuestions(obj.questions) };
  }
  return { summary: "", questions: [] };
}

/** Draft the Prepared for you section. Costs one AI credit; the credit is refunded by
 *  runAi if the call fails, so a failure never charges them. */
export async function draftReturnToWork(
  _prev: ActionState,
  formData: FormData,
): Promise<ActionState> {
  const { profile } = await requireCompany();
  if (!profile.company_id) return { error: "No company context." };
  // Not On Call (Phil, 11 Oct 2026): asked before any credit is spent (lib/absence/rtw-roles.ts).
  if (!canRecordReturnToWork(profile.role)) return { error: RTW_ROLE_REFUSAL };
  const absenceId = String(formData.get("absence_event_id") ?? "");
  if (!absenceId) return { error: "Missing absence." };

  /* DRAFTED ONCE, KEPT (Phil, 2026-09-25): "when that is drafted it stays for that specific
     return to work, so it stops using ai credits". If this absence already has saved questions,
     hand those back and spend nothing. */
  const saved = await getRtwQuestionnaire(absenceId);
  if (saved && saved.questions.length > 0) {
    return {
      ok: "Drafted",
      data: { absence_summary: saved.summary ?? "", ai_questions: JSON.stringify(saved.questions) },
    } as ActionState;
  }

  const ctx = await getRtwContext(absenceId);
  if (!ctx) return { error: "That absence could not be found." };

  /* ONLY THIS ABSENCE (rule A, and UK GDPR data minimisation): its dates and its reason, with the
     employee's name taken out. No other absence, stage, score, count or name goes to the AI. */
  const absence: RtwAbsence = {
    startDate: ctx.startDate,
    endDate: ctx.endDate,
    reason: ctx.reason ? redactName(ctx.reason, ctx.personName) : null,
  };
  const prompt = rtwDraftPrompt(absence);

  const result = await runAi({
    companyId: profile.company_id,
    feature: "return_to_work",
    prompt,
    system: RTW_SYSTEM,
    maxTokens: 1600,
  });
  if ("error" in result) return { error: result.error };

  const drafted = readDraft(result.ok);
  /* THE CHECK (rules A, C, D, E), in code, before anything is saved or shown: whatever the AI wrote,
     a question about another absence, a fit note under 8 days or work as a cause for a cold never
     reaches the employee, and the required questions are always there. Logged as codes only. */
  const checked = checkRtwDraft(drafted.questions, absence, AI_QUESTION_LIMIT);
  const summaryCheck = checkRtwSummary(drafted.summary, absence);
  const summary = summaryCheck.summary;
  const questions = checked.questions as AiQuestion[];
  if (checked.removed.length > 0 || checked.added.length > 0 || summaryCheck.removed > 0) {
    console.info("[rtw-draft] check", {
      removed: checked.removed,
      added: checked.added,
      summarySentencesRemoved: summaryCheck.removed,
    });
  }
  if (questions.length > 0) {
    // Save it to this Return to Work straight away, so the next press reads it back for free
    // and the questions can be checked and texted to the employee (migration 0331).
    const supabase = await createClient();
    const { data: ev } = await supabase
      .from("absence_events")
      .select("person_id, branch_id")
      .eq("id", absenceId)
      .maybeSingle();
    if (ev) {
      const { error: insErr } = await supabase.from("rtw_questionnaires").insert({
        company_id: profile.company_id,
        absence_event_id: absenceId,
        person_id: ev.person_id,
        branch_id: ev.branch_id ?? null,
        summary,
        questions,
        drafted_by: profile.id,
        drafted_by_name: profile.full_name,
      });
      // Two people pressing at once: the first draft wins and both see it.
      if (insErr) {
        const won = await getRtwQuestionnaire(absenceId);
        if (won && won.questions.length > 0) {
          return {
            ok: "Drafted",
            data: { absence_summary: won.summary ?? "", ai_questions: JSON.stringify(won.questions) },
          } as ActionState;
        }
      }
    }
    return {
      ok: "Drafted",
      // absence_summary is a real field key and is merged straight into the answers.
      // ai_questions is NOT a field: the dialog pulls it out, renders a control per
      // question, and writes the answers into tailored_questions on save.
      data: { absence_summary: summary, ai_questions: JSON.stringify(questions) },
    } as ActionState;
  }
  /* Unreachable in practice: the check always returns at least the required questions, so even a
     reply that could not be read gives a set that follows the rules, never unchecked text. */
  return { error: "The draft could not be read. Please try again." };
}

/** Record the completed interview as Evidence and close the Return to Work off. */
export async function recordReturnToWork(
  _prev: ActionState,
  formData: FormData,
): Promise<ActionState> {
  const { user, profile } = await requireCompany();
  if (!profile.company_id) return { error: "No company context." };
  /* Not On Call (Phil, 11 Oct 2026). The database refuses their Return to Work form too (0444,
     may_file_evidence); asked here first so the answer is plain and nothing is uploaded. */
  if (!canRecordReturnToWork(profile.role)) return { error: RTW_ROLE_REFUSAL };
  const absenceId = String(formData.get("absence_event_id") ?? "");
  if (!absenceId) return { error: "Missing absence." };

  let answers: Answers;
  try {
    answers = JSON.parse(String(formData.get("answers") ?? "{}")) as Answers;
  } catch {
    return { error: "Could not read the form answers." };
  }

  const supabase = await createClient();
  const { data: absence } = await supabase
    .from("absence_events")
    .select("id, person_id, branch_id, rtw_evidence_id, rtw_cancelled_at")
    .eq("id", absenceId)
    .maybeSingle();
  if (!absence) return { error: "That absence could not be found." };
  if (absence.rtw_evidence_id) {
    return { error: "A Return to Work has already been recorded for this absence." };
  }
  if (absence.rtw_cancelled_at) {
    return { error: "This Return to Work was cancelled. A Manager can reinstate it from View absence first." };
  }

  const form = await getCompanyFormByKey(profile.company_id, "return_to_work");
  if (!form) return { error: "The Return to Work form is not available for your company yet." };

  /* THE EMPLOYEE'S OWN ANSWERS (0331). When they answered through their portal, say so at the
     top of the answers, and say which ones the interviewer changed after ringing them. The
     final answers come from the dialog; what the employee sent is read back from the database,
     never taken from the browser. */
  const questionnaire = await getRtwQuestionnaire(absenceId);
  let changed: number[] = [];
  if (questionnaire?.status === "answered" && questionnaire.answers) {
    let finalAnswers: string[] = [];
    try {
      const posted = JSON.parse(String(formData.get("ai_questions_json") ?? "{}")) as { answers?: unknown };
      if (Array.isArray(posted.answers)) finalAnswers = posted.answers.map((a) => String(a ?? ""));
    } catch {
      finalAnswers = [];
    }
    if (finalAnswers.length > 0) changed = changedAnswerNumbers(questionnaire.answers, finalAnswers);
    const { data: who } = await supabase
      .from("people")
      .select("full_name")
      .eq("id", absence.person_id as string)
      .maybeSingle();
    const note = rtwProvenanceNote({
      firstName: String(who?.full_name ?? "").trim().split(/\s+/)[0] ?? "",
      answeredAtIso: questionnaire.answeredAt ?? new Date().toISOString(),
      changed,
      changedByName: profile.full_name,
    });
    const existing = typeof answers.tailored_questions === "string" ? answers.tailored_questions : "";
    answers = { ...answers, tailored_questions: existing ? `${note}\n\n${existing}` : note };
  }

  const files: EvidenceFileInput[] = [];
  for (const [key, value] of formData.entries()) {
    if (key.startsWith("file:") && value instanceof File && value.size > 0) {
      files.push({
        fieldKey: key.slice(5),
        kind: "upload",
        fileName: value.name,
        contentType: value.type || "application/octet-stream",
        bytes: Buffer.from(await value.arrayBuffer()),
      });
    }
  }

  /* THE FIT NOTE THEY UPLOADED (0344) is filed into this Evidence, unless the interviewer
     attached one themselves. Read with the service role: the file is in the private bucket and
     the row has already been checked through RLS above. */
  let fitNotePath: string | null = null;
  const fitField = (form.schema as { sections?: Array<{ fields?: Array<{ key?: string }> }> } | null)
    ?.sections?.some((sec) => sec.fields?.some((f) => f.key === "fit_note"));
  if (questionnaire?.hasFitNote && fitField && !files.some((f) => f.fieldKey === "fit_note")) {
    const { data: fn } = await supabase
      .from("rtw_questionnaires")
      .select("fit_note_path, fit_note_name, fit_note_type")
      .eq("id", questionnaire.id)
      .maybeSingle();
    if (fn?.fit_note_path) {
      const { data: blob, error: dlErr } = await createServiceClient()
        .storage.from("evidence")
        .download(fn.fit_note_path as string);
      if (dlErr || !blob) {
        return { error: `Their fit note could not be read, so nothing was saved: ${dlErr?.message ?? "no file"}. Try again.` };
      }
      const fileName = (fn.fit_note_name as string | null) || "fit-note";
      files.push({
        fieldKey: "fit_note",
        kind: "upload",
        fileName,
        contentType: (fn.fit_note_type as string | null) || blob.type || "application/octet-stream",
        bytes: Buffer.from(await blob.arrayBuffer()),
      });
      answers = { ...answers, fit_note: fileName };
      fitNotePath = fn.fit_note_path as string;
    }
  }

  const result = await submitEvidence({
    formVersionId: form.versionId,
    branchId: (absence.branch_id as string | null) ?? null,
    answers,
    files,
    recordType: "person",
    recordId: absence.person_id as string,
  });
  if (!result.ok) return { error: result.error };

  // Check the update landed: an RLS refusal returns no rows and no error, which would
  // otherwise leave the Return to Work showing as still outstanding forever.
  const { data: updated, error: updErr } = await supabase
    .from("absence_events")
    .update({ rtw_evidence_id: result.evidenceId })
    .eq("id", absenceId)
    .is("rtw_evidence_id", null)
    .select("id");
  if (updErr || !updated || updated.length === 0) {
    return { error: "The interview was saved as Evidence but the absence could not be updated." };
  }

  // The questions are finished with: the link in the text stops working, and the tile stops
  // saying "Answers in".
  if (questionnaire && questionnaire.status !== "recorded") {
    // The fit note now lives in the Evidence (and follows its retention); the waiting copy goes.
    if (fitNotePath) await createServiceClient().storage.from("evidence").remove([fitNotePath]);
    await supabase
      .from("rtw_questionnaires")
      .update({
        status: "recorded",
        ...(fitNotePath ? { fit_note_path: null, fit_note_evidence_id: result.evidenceId } : {}),
        ...(changed.length > 0
          ? {
              answers_changed_at: new Date().toISOString(),
              answers_changed_by: profile.id,
              answers_changed_by_name: profile.full_name,
            }
          : {}),
      })
      .eq("id", questionnaire.id);
  }

  await writeAudit({
    companyId: profile.company_id,
    actorId: user.id,
    actorEmail: profile.email,
    actorRole: profile.role,
    action: "absence.return_to_work_recorded",
    entityType: "person",
    entityId: absence.person_id as string,
    summary: "Recorded a Return to Work interview",
    metadata: { absence_event_id: absenceId, evidence_id: result.evidenceId },
  });

  revalidatePath("/people/absence");
  revalidatePath("/dashboard");
  revalidatePath(`/people/${absence.person_id}`);
  return { ok: "Recorded", redirectTo: `/people/absence` };
}
